const separateParenGroups = (paren_string) => {
  const result = [];
  let current = '';
  let depth = 0;
  for (const ch of paren_string) {
    if (ch === ' ') continue;
    if (ch === '(') {
      depth++;
      current += ch;
    } else if (ch === ')') {
      depth--;
      current += ch;
      if (depth === 0) {
        result.push(current);
        current = '';
      }
    }
  }
  return result;
};
